-- Forward-only Restaurant & F&B operational extension: staff shifts, modifiers, promotions, purchasing, bill splits, refunds, and reporting support.
BEGIN;
CREATE TABLE IF NOT EXISTS public.restaurant_combo_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, parent_menu_item_id uuid NOT NULL REFERENCES public.restaurant_menu_items(id) ON DELETE CASCADE, child_menu_item_id uuid NOT NULL REFERENCES public.restaurant_menu_items(id) ON DELETE RESTRICT, quantity numeric(18,3) NOT NULL DEFAULT 1 CHECK(quantity>0), UNIQUE(parent_menu_item_id,child_menu_item_id));
CREATE TABLE IF NOT EXISTS public.restaurant_promotions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, discount_type text NOT NULL CHECK(discount_type IN ('Percent','Amount')), discount_value numeric(18,2) NOT NULL CHECK(discount_value>=0), starts_at timestamptz NOT NULL DEFAULT now(), ends_at timestamptz, status text NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive')), UNIQUE(company_id,code));
CREATE TABLE IF NOT EXISTS public.restaurant_bill_splits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, parent_order_id uuid NOT NULL REFERENCES public.restaurant_orders(id) ON DELETE CASCADE, split_order_id uuid NOT NULL REFERENCES public.restaurant_orders(id) ON DELETE CASCADE, split_number integer NOT NULL, amount numeric(18,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Settled','Cancelled')), UNIQUE(parent_order_id,split_number));
CREATE TABLE IF NOT EXISTS public.restaurant_refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, order_id uuid NOT NULL REFERENCES public.restaurant_orders(id) ON DELETE RESTRICT, payment_id uuid REFERENCES public.restaurant_payments(id) ON DELETE SET NULL, reason text NOT NULL, amount numeric(18,2) NOT NULL CHECK(amount>0), status text NOT NULL DEFAULT 'Completed' CHECK(status IN ('Completed','Voided')), idempotency_key text NOT NULL, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,idempotency_key));
CREATE INDEX IF NOT EXISTS restaurant_purchase_requests_outlet_status_idx ON public.restaurant_purchase_requests(company_id,outlet_id,status,created_at DESC);

CREATE OR REPLACE FUNCTION public.restaurant_operations_snapshot() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid:=public.current_company_id(); BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'An authenticated restaurant session is required.' USING ERRCODE='28000'; END IF; RETURN jsonb_build_object('inventory',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM public.inventory_items x WHERE x.company_id=c LIMIT 500),'[]'::jsonb),'employees',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM public.hr_employees x WHERE x.company_id=c AND x.status='Active' LIMIT 500),'[]'::jsonb),'roles',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.restaurant_staff_roles x WHERE x.company_id=c),'[]'::jsonb),'shifts',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.starts_at DESC) FROM public.restaurant_shifts x WHERE x.company_id=c LIMIT 200),'[]'::jsonb),'modifiers',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.restaurant_modifier_groups x WHERE x.company_id=c),'[]'::jsonb),'modifierOptions',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.restaurant_modifier_options x WHERE x.company_id=c),'[]'::jsonb),'combos',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.restaurant_combo_items x WHERE x.company_id=c),'[]'::jsonb),'suppliers',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM public.restaurant_suppliers x WHERE x.company_id=c),'[]'::jsonb),'purchaseRequests',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.restaurant_purchase_requests x WHERE x.company_id=c LIMIT 200),'[]'::jsonb),'purchaseLines',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.restaurant_purchase_lines x WHERE x.company_id=c),'[]'::jsonb),'promotions',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.restaurant_promotions x WHERE x.company_id=c),'[]'::jsonb),'splits',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.restaurant_bill_splits x WHERE x.company_id=c),'[]'::jsonb),'refunds',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.restaurant_refunds x WHERE x.company_id=c LIMIT 200),'[]'::jsonb)); END $$;
CREATE OR REPLACE FUNCTION public.restaurant_operations_action(p_action text,p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid:=public.current_company_id(); v_id uuid; v_order public.restaurant_orders%ROWTYPE; v_line record; v_total numeric; v_i record; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'An authenticated restaurant session is required.' USING ERRCODE='28000'; END IF;
IF p_action='STAFF_ROLE_ASSIGN' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.' USING ERRCODE='42501'; END IF; INSERT INTO public.restaurant_staff_roles(company_id,outlet_id,employee_id,role) VALUES(c,nullif(p_payload->>'outletId','')::uuid,(p_payload->>'employeeId')::uuid,p_payload->>'role') ON CONFLICT(outlet_id,employee_id,role) DO UPDATE SET status='Active' RETURNING id INTO v_id;
ELSIF p_action='SHIFT_OPEN' THEN IF NOT public.restaurant_can_operate(ARRAY['Cashier','Waiter','Kitchen','Bar','Restaurant Manager']) THEN RAISE EXCEPTION 'Restaurant staff permission required.'; END IF; INSERT INTO public.restaurant_shifts(company_id,outlet_id,employee_id,role,starts_at,opening_cash) VALUES(c,(p_payload->>'outletId')::uuid,(p_payload->>'employeeId')::uuid,p_payload->>'role',coalesce(nullif(p_payload->>'startsAt','')::timestamptz,now()),coalesce(nullif(p_payload->>'openingCash','')::numeric,0)) RETURNING id INTO v_id;
ELSIF p_action='SHIFT_CLOSE' THEN IF NOT public.restaurant_can_operate(ARRAY['Cashier','Restaurant Manager','Finance']) THEN RAISE EXCEPTION 'Cashier or manager permission required.'; END IF; UPDATE public.restaurant_shifts SET status='Closed',ends_at=now(),closing_cash=(p_payload->>'closingCash')::numeric WHERE id=(p_payload->>'shiftId')::uuid AND company_id=c AND status='Open' RETURNING id INTO v_id; IF v_id IS NULL THEN RAISE EXCEPTION 'Open shift not found.' USING ERRCODE='P0002'; END IF;
ELSIF p_action='MODIFIER_GROUP_SAVE' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.'; END IF; INSERT INTO public.restaurant_modifier_groups(company_id,outlet_id,name,min_select,max_select) VALUES(c,(p_payload->>'outletId')::uuid,p_payload->>'name',coalesce(nullif(p_payload->>'minSelect','')::integer,0),coalesce(nullif(p_payload->>'maxSelect','')::integer,1)) RETURNING id INTO v_id;
ELSIF p_action='MODIFIER_OPTION_SAVE' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.'; END IF; INSERT INTO public.restaurant_modifier_options(company_id,group_id,inventory_item_id,name,price_delta) VALUES(c,(p_payload->>'groupId')::uuid,nullif(p_payload->>'inventoryItemId','')::uuid,p_payload->>'name',coalesce(nullif(p_payload->>'priceDelta','')::numeric,0)) RETURNING id INTO v_id;
ELSIF p_action='COMBO_ITEM_SAVE' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.'; END IF; INSERT INTO public.restaurant_combo_items(company_id,parent_menu_item_id,child_menu_item_id,quantity) VALUES(c,(p_payload->>'parentMenuItemId')::uuid,(p_payload->>'childMenuItemId')::uuid,coalesce(nullif(p_payload->>'quantity','')::numeric,1)) ON CONFLICT(parent_menu_item_id,child_menu_item_id) DO UPDATE SET quantity=excluded.quantity RETURNING id INTO v_id;
ELSIF p_action='PROMOTION_SAVE' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.'; END IF; INSERT INTO public.restaurant_promotions(company_id,outlet_id,code,name,discount_type,discount_value,starts_at,ends_at) VALUES(c,(p_payload->>'outletId')::uuid,upper(p_payload->>'code'),p_payload->>'name',p_payload->>'discountType',(p_payload->>'discountValue')::numeric,coalesce(nullif(p_payload->>'startsAt','')::timestamptz,now()),nullif(p_payload->>'endsAt','')::timestamptz) RETURNING id INTO v_id;
ELSIF p_action='SUPPLIER_SAVE' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.'; END IF; INSERT INTO public.restaurant_suppliers(company_id,name,phone,email,address) VALUES(c,p_payload->>'name',p_payload->>'phone',p_payload->>'email',p_payload->>'address') RETURNING id INTO v_id;
ELSIF p_action='PURCHASE_REQUEST_CREATE' THEN IF NOT public.restaurant_can_operate(ARRAY['Storekeeper','Restaurant Manager']) THEN RAISE EXCEPTION 'Restaurant purchasing permission required.'; END IF; IF jsonb_typeof(p_payload->'lines')<>'array' OR jsonb_array_length(p_payload->'lines')=0 THEN RAISE EXCEPTION 'Purchase request requires at least one inventory line.' USING ERRCODE='22023'; END IF; INSERT INTO public.restaurant_purchase_requests(company_id,outlet_id,supplier_id,request_number,status,total_amount,currency,data) VALUES(c,(p_payload->>'outletId')::uuid,nullif(p_payload->>'supplierId','')::uuid,coalesce(nullif(p_payload->>'requestNumber',''),'RPO-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),'Submitted',0,coalesce(p_payload->>'currency','TZS'),coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id; FOR v_i IN SELECT value FROM jsonb_array_elements(p_payload->'lines') LOOP INSERT INTO public.restaurant_purchase_lines(company_id,request_id,inventory_item_id,quantity,unit_cost) VALUES(c,v_id,(v_i.value->>'inventoryItemId')::uuid,(v_i.value->>'quantity')::numeric,coalesce(nullif(v_i.value->>'unitCost','')::numeric,0)); END LOOP; UPDATE public.restaurant_purchase_requests SET total_amount=coalesce((SELECT sum(quantity*unit_cost) FROM public.restaurant_purchase_lines WHERE request_id=v_id),0) WHERE id=v_id;
ELSIF p_action='PURCHASE_RECEIVE' THEN IF NOT public.restaurant_can_operate(ARRAY['Storekeeper','Restaurant Manager']) THEN RAISE EXCEPTION 'Restaurant receiving permission required.'; END IF; FOR v_i IN SELECT pl.*,i.name,coalesce(nullif(i.data->>'qty_on_hand','')::numeric,nullif(i.data->>'quantity','')::numeric,0) stock FROM public.restaurant_purchase_lines pl JOIN public.inventory_items i ON i.id=pl.inventory_item_id WHERE pl.request_id=(p_payload->>'requestId')::uuid AND pl.company_id=c FOR UPDATE LOOP UPDATE public.inventory_items SET data=jsonb_set(data,'{qty_on_hand}',to_jsonb(v_i.stock+v_i.quantity),true),updated_at=now() WHERE id=v_i.inventory_item_id; UPDATE public.restaurant_purchase_lines SET received_quantity=quantity WHERE id=v_i.id; INSERT INTO public.inventory_stock_movements(company_id,name,status,amount,notes,data) VALUES(c,v_i.name,'In',v_i.quantity,'Restaurant purchase receipt',jsonb_build_object('source','restaurant_purchase_request','request_id',v_i.request_id,'movement','In','qty',v_i.quantity)); END LOOP; UPDATE public.restaurant_purchase_requests SET status='Received' WHERE id=(p_payload->>'requestId')::uuid AND company_id=c RETURNING id INTO v_id;
ELSIF p_action='BILL_SPLIT_CREATE' THEN IF NOT public.restaurant_can_operate(ARRAY['Cashier','Restaurant Manager']) THEN RAISE EXCEPTION 'Cashier or manager permission required.'; END IF; SELECT * INTO v_order FROM public.restaurant_orders WHERE id=(p_payload->>'orderId')::uuid AND company_id=c FOR UPDATE; IF NOT FOUND OR v_order.status NOT IN ('Ready','Served') THEN RAISE EXCEPTION 'Only a ready or served order can be split.' USING ERRCODE='55000'; END IF; v_total:=coalesce((SELECT sum(quantity*unit_price-discount_amount) FROM public.restaurant_order_lines WHERE order_id=v_order.id AND status<>'Voided'),0); IF coalesce(nullif(p_payload->>'parts','')::integer,0)<2 THEN RAISE EXCEPTION 'Bill split requires at least two parts.' USING ERRCODE='22023'; END IF; FOR v_i IN SELECT generate_series(1,(p_payload->>'parts')::integer) AS n LOOP INSERT INTO public.restaurant_orders(company_id,outlet_id,customer_id,order_number,order_type,status,subtotal,total_amount,currency,data) VALUES(c,v_order.outlet_id,v_order.customer_id,v_order.order_number||'-S'||v_i.n,'Takeaway','Ready',round(v_total/(p_payload->>'parts')::integer,2),round(v_total/(p_payload->>'parts')::integer,2),v_order.currency,jsonb_build_object('parentOrderId',v_order.id)) RETURNING id INTO v_id; INSERT INTO public.restaurant_bill_splits(company_id,parent_order_id,split_order_id,split_number,amount) VALUES(c,v_order.id,v_id,v_i.n,round(v_total/(p_payload->>'parts')::integer,2)); END LOOP; UPDATE public.restaurant_orders SET status='Cancelled',data=data||jsonb_build_object('splitIntoParts',(p_payload->>'parts')::integer) WHERE id=v_order.id; v_id:=v_order.id;
ELSIF p_action='REFUND_PROCESS' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.'; END IF; SELECT * INTO v_order FROM public.restaurant_orders WHERE id=(p_payload->>'orderId')::uuid AND company_id=c AND status='Paid' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'A paid Restaurant order is required for a refund.' USING ERRCODE='P0002'; END IF; v_total:=coalesce(nullif(p_payload->>'amount','')::numeric,0); IF v_total<=0 OR v_total>v_order.total_amount THEN RAISE EXCEPTION 'Refund amount is outside the paid order balance.' USING ERRCODE='22023'; END IF; INSERT INTO public.restaurant_refunds(company_id,order_id,payment_id,reason,amount,idempotency_key) VALUES(c,v_order.id,nullif(p_payload->>'paymentId','')::uuid,p_payload->>'reason',v_total,p_payload->>'idempotencyKey') RETURNING id INTO v_id; INSERT INTO public.sales_payments(company_id,name,status,amount,notes,data) VALUES(c,'Restaurant refund · '||v_order.order_number,'Refunded',-v_total,p_payload->>'reason',jsonb_build_object('source','restaurant_refund','refund_id',v_id,'order_id',v_order.id)); INSERT INTO public.journal_entries(company_id,name,status,amount,notes,data) VALUES(c,'Restaurant refund: '||v_order.order_number,'Posted',-v_total,'Restaurant refund',jsonb_build_object('source','restaurant_refund','refund_id',v_id)); UPDATE public.restaurant_orders SET status=CASE WHEN v_total=v_order.total_amount THEN 'Refunded' ELSE status END WHERE id=v_order.id;
ELSE RAISE EXCEPTION 'Unsupported restaurant operations action: %',p_action USING ERRCODE='22023'; END IF; PERFORM public.restaurant_audit(p_action,'RestaurantOperation',v_id,p_payload); RETURN jsonb_build_object('ok',true,'recordId',v_id,'snapshotRequired',true); END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['restaurant_combo_items','restaurant_promotions','restaurant_bill_splits','restaurant_refunds'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',t||'_tenant_read',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (company_id=public.current_company_id())',t||'_tenant_read',t); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.restaurant_operations_snapshot() FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.restaurant_operations_action(text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.restaurant_operations_snapshot() TO authenticated; GRANT EXECUTE ON FUNCTION public.restaurant_operations_action(text,jsonb) TO authenticated;
COMMIT;
